from jsonschema import Draft202012Validator, ValidationError

def ask_with_repair(doc, prompt, tries=2):
    out = call_model(prompt, doc)
    for _ in range(tries):
        try:
            Draft202012Validator(CARD).validate(out)
            return out
        except ValidationError as e:
            out = call_model(prompt, doc, previous=out, error=e.message)
    return None

